CREATE POLICY "citizen_files_read_own" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'citizen-files' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "citizen_files_create_own" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'citizen-files' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "citizen_files_update_own" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'citizen-files' AND (storage.foldername(name))[1] = auth.uid()::text) WITH CHECK (bucket_id = 'citizen-files' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "citizen_files_delete_own" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'citizen-files' AND (storage.foldername(name))[1] = auth.uid()::text);